//! The synthetic fixtures under `testdata/golden/escritorio/` (generated by
//! `testdata/synth/formatos_escritorio.py`) parse into the expected tables, items, entries
//! and warnings through the same dispatcher a run uses.

use std::path::PathBuf;

use chrono::NaiveDate;
use dm_core::{ColumnRole, Item, ItemKind, Money, Table, Value};
use dm_ingest::{parse_bytes, InboxContext, ParsedSource, SourceKind};

fn golden(path: &str) -> PathBuf {
    PathBuf::from(
        std::env::var("CARGO_MANIFEST_DIR")
            .expect("cargo define CARGO_MANIFEST_DIR ao rodar os testes"),
    )
    .join("../../../../testdata/golden")
    .join(path)
}

fn parse(path: &str) -> ParsedSource {
    let file = golden(path);
    let bytes = std::fs::read(&file).unwrap_or_else(|e| panic!("{}: {e}", file.display()));
    let name = file
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or_default()
        .to_string();
    parse_bytes(&name, &bytes, &InboxContext::default()).unwrap_or_else(|e| panic!("{e}"))
}

fn cell<'a>(t: &'a Table, row: usize, col: &str) -> &'a Value {
    let c = t
        .column_index(col)
        .unwrap_or_else(|| panic!("{}: sem coluna {col}", t.name));
    t.value(row, c)
        .unwrap_or_else(|| panic!("{}: sem linha {row}", t.name))
}

fn role(t: &Table, col: &str) -> ColumnRole {
    t.columns
        .iter()
        .find(|c| c.name == col)
        .map_or(ColumnRole::Unknown, |c| c.role)
}

fn money(t: &Table, row: usize, col: &str) -> Option<i64> {
    cell(t, row, col).as_money().map(Money::centavos)
}

fn field<'a>(item: &'a Item, name: &str) -> Option<&'a str> {
    item.fields.get(name).and_then(Value::as_text)
}

fn events(src: &ParsedSource) -> Vec<&Item> {
    src.items
        .iter()
        .filter(|i| i.kind == ItemKind::Event)
        .collect()
}

fn all_text(src: &ParsedSource) -> String {
    src.items
        .iter()
        .filter_map(Item::text)
        .collect::<Vec<_>>()
        .join("\n")
}

#[test]
fn docx_email_with_an_installments_table() {
    let src = parse("escritorio/instrucao_pagamento.docx");
    assert_eq!(src.sniff.kind, SourceKind::Docx);
    assert!(src.warnings.is_empty(), "{:?}", src.warnings);
    assert_eq!(src.tables.len(), 1, "the signature grid is layout");
    let t = &src.tables[0];
    assert_eq!(t.name, "instrucao_pagamento:tabela 1");
    assert_eq!(t.len(), 2);
    assert_eq!(role(t, "vencimento"), ColumnRole::Date);
    assert_eq!(role(t, "valor"), ColumnRole::Amount);
    assert_eq!(cell(t, 1, "documento"), &Value::Text("NF 55120-2".into()));
    assert_eq!(money(t, 0, "valor"), Some(749_700));
    // The pasted e-mail is a message of the inbox.
    let mail = events(&src);
    assert_eq!(mail.len(), 1);
    assert_eq!(
        field(mail[0], "from"),
        Some("financeiro@caixasboavista.invalid")
    );
    assert_eq!(
        field(mail[0], "subject"),
        Some("Instrução de pagamento - NF 55120")
    );
    assert_eq!(field(mail[0], "date"), Some("18/07/2026 16:52"));
    let text = all_text(&src);
    assert!(text.contains("Dados bancários: Banco 341"), "{text}");
    assert!(
        text.contains("Ana Lima\nFinanceiro - Caixas Boa Vista\t(11) 0000-0000"),
        "{text}"
    );
    assert!(
        !text.contains("Valor antigo"),
        "tracked deletions are not text"
    );
    assert!(!text.contains("7.497,00"), "data tables are not text");
}

#[test]
fn odt_titles_table_and_paragraphs() {
    let src = parse("escritorio/titulos_em_aberto.odt");
    assert_eq!(src.sniff.kind, SourceKind::Odt);
    assert!(src.warnings.is_empty(), "{:?}", src.warnings);
    let t = &src.tables[0];
    assert_eq!(t.columns.len(), 6, "repeated empty cells are not columns");
    assert_eq!(t.len(), 3);
    assert_eq!(role(t, "cliente"), ColumnRole::Name);
    assert_eq!(role(t, "cnpj"), ColumnRole::TaxId);
    assert_eq!(role(t, "situacao"), ColumnRole::Status);
    assert_eq!(
        cell(t, 1, "cliente"),
        &Value::Text("Empório Bela Vista".into())
    );
    assert_eq!(cell(t, 0, "cnpj"), &Value::Text("11222333000181".into()));
    assert_eq!(money(t, 1, "valor"), Some(245_090));
    let text = all_text(&src);
    assert!(
        text.contains("Relatório  gerado\tpelo financeiro."),
        "{text}"
    );
    assert!(text.contains("Total em aberto: R$ 19.830,90"));
    assert!(
        !text.contains("comentário do revisor"),
        "annotations are not text"
    );
    assert!(events(&src).iter().all(|e| field(e, "from").is_none()));
}

#[test]
fn outlook_message_attachments_and_attached_message() {
    let src = parse("escritorio/boleto_atualizado.msg");
    assert_eq!(src.sniff.kind, SourceKind::Msg);
    assert!(src.warnings.is_empty(), "{:?}", src.warnings);
    let mail = events(&src);
    assert_eq!(mail.len(), 1);
    let m = mail[0];
    assert_eq!(
        field(m, "from"),
        Some("Ana Lima <ana.lima@caixasboavista.invalid>")
    );
    assert_eq!(
        field(m, "to"),
        Some("Contas a Pagar <pagar@exemplo-sintetico.invalid>")
    );
    assert_eq!(
        field(m, "cc"),
        Some("Compras <compras@exemplo-sintetico.invalid>")
    );
    assert_eq!(
        field(m, "subject"),
        Some("RE: cobrança em aberto - Caixas Boa Vista")
    );
    // The sender's local time from the transport headers, as an .eml gives it.
    assert_eq!(field(m, "date"), Some("18/07/2026 16:52"));
    assert_eq!(
        field(m, "message_id"),
        Some("<boleto-55120@caixasboavista.invalid>")
    );
    assert_eq!(
        field(m, "attachments"),
        Some("extrato_jul2026.csv; cobranca em aberto.msg"),
        "the inline signature image is not an attachment"
    );
    assert_eq!(field(m, "sender_domain"), Some("caixasboavista.invalid"));
    assert!(m
        .entity_mentions
        .iter()
        .any(|x| x.normalized.as_deref() == Some("1499400")));
    assert_eq!(
        src.items
            .iter()
            .filter(|i| i.kind == ItemKind::TextSpan)
            .count(),
        3
    );
    // The CSV attachment is a source of its own; the attached message is read too, but its
    // own attachment is not opened.
    let names: Vec<&str> = src.entries.iter().map(|e| e.name.as_str()).collect();
    assert_eq!(
        names,
        vec![
            "boleto_atualizado.msg/extrato_jul2026.csv",
            "boleto_atualizado.msg/cobranca em aberto.msg",
        ]
    );
    let csv = &src.entries[0];
    assert_eq!(csv.sniff.kind, SourceKind::Csv);
    assert_eq!(csv.tables[0].len(), 18);
    assert_eq!(csv.tables[0].name, "extrato_jul2026");
    assert_ne!(csv.source_id, src.source_id);
    let inner = &src.entries[1];
    assert_eq!(inner.sniff.kind, SourceKind::Msg);
    let inner_mail = events(inner);
    assert_eq!(
        field(inner_mail[0], "from"),
        Some("Contas a Pagar <pagar@exemplo-sintetico.invalid>")
    );
    assert_eq!(field(inner_mail[0], "attachments"), Some("comprovante.pdf"));
    assert_eq!(
        inner.warnings,
        vec!["boleto_atualizado.msg/cobranca em aberto.msg: anexos da mensagem anexada não são abertos (profundidade máxima 1)".to_string()]
    );
    assert!(inner.entries.is_empty());
}

#[test]
fn json_records_with_nested_keys() {
    let src = parse("escritorio/titulos_api.json");
    assert_eq!(src.sniff.kind, SourceKind::Json);
    assert!(src.warnings.is_empty(), "{:?}", src.warnings);
    assert_eq!(src.tables.len(), 1);
    let t = &src.tables[0];
    assert_eq!(t.name, "titulos_api:titulos");
    assert_eq!(t.len(), 2);
    assert_eq!(role(t, "cliente_nome"), ColumnRole::Name);
    assert_eq!(role(t, "cliente_cnpj"), ColumnRole::TaxId);
    assert_eq!(role(t, "vencimento"), ColumnRole::Date);
    assert_eq!(money(t, 0, "valor"), Some(2_785_000));
    assert_eq!(money(t, 1, "valor"), Some(1_045_000));
    assert_eq!(cell(t, 1, "pago"), &Value::Bool(true));
    assert_eq!(cell(t, 0, "tags"), &Value::Text("royalty; sul".into()));
    assert_eq!(
        cell(t, 0, "vencimento").as_date(),
        NaiveDate::from_ymd_opt(2026, 7, 20)
    );
}

#[test]
fn json_lines_skip_a_broken_line_with_a_warning() {
    let src = parse("escritorio/lancamentos_jul2026.jsonl");
    assert_eq!(src.sniff.kind, SourceKind::Jsonl);
    assert_eq!(
        src.warnings,
        vec![
            "lancamentos_jul2026.jsonl: 1 linha(s) que não são objetos JSON foram ignoradas: 3"
                .to_string()
        ]
    );
    let t = &src.tables[0];
    assert_eq!(t.len(), 4);
    assert_eq!(role(t, "historico"), ColumnRole::FreeText);
    assert_eq!(money(t, 3, "valor"), Some(4_376_050));
}

#[test]
fn generic_xml_repeated_records_in_latin1() {
    let src = parse("escritorio/extrato_jul2026.xml");
    assert_eq!(src.sniff.kind, SourceKind::Xml);
    assert!(src.warnings.is_empty(), "{:?}", src.warnings);
    let t = &src.tables[0];
    assert_eq!(t.name, "extrato_jul2026:extrato.lancamentos.lancamento");
    assert_eq!(t.len(), 6);
    let names: Vec<&str> = t.columns.iter().map(|c| c.name.as_str()).collect();
    assert_eq!(
        names,
        vec![
            "data",
            "historico",
            "documento",
            "valor",
            "valor_moeda",
            "tipo",
            "seq"
        ]
    );
    assert_eq!(
        role(t, "valor_moeda"),
        ColumnRole::Unknown,
        "attributes take no role from their values"
    );
    assert_eq!(cell(t, 0, "documento"), &Value::Text("000098765001".into()));
    assert_eq!(cell(t, 1, "documento"), &Value::Null);
    assert_eq!(money(t, 5, "valor"), Some(98_000));
}

#[test]
fn saved_statement_page() {
    let src = parse("escritorio/extrato_internet_banking.html");
    assert_eq!(src.sniff.kind, SourceKind::Html);
    assert!(src.warnings.is_empty(), "{:?}", src.warnings);
    assert_eq!(src.tables.len(), 1);
    let t = &src.tables[0];
    assert_eq!(t.name, "extrato_internet_banking:tabela 2");
    assert_eq!(t.len(), 5);
    assert_eq!(role(t, "historico"), ColumnRole::FreeText);
    assert_eq!(role(t, "tipo"), ColumnRole::Kind);
    assert_eq!(money(t, 3, "valor_r"), Some(4_376_050));
    let text = all_text(&src);
    assert!(
        text.contains("Banco Sintético S.A. · Internet Banking Empresas"),
        "{text}"
    );
    assert!(text.contains("Extrato emitido em 31/07/2026 às 23:59."));
    assert!(!text.contains("sessão"), "hidden elements are not text");
    assert!(!text.contains("var linhas"), "scripts are not text");
}

#[test]
fn sevenz_entries_are_sources_of_their_own() {
    let src = parse("escritorio/pacote_jul2026.7z");
    assert_eq!(src.sniff.kind, SourceKind::SevenZ);
    assert_eq!(
        src.warnings,
        vec!["pacote_jul2026.7z/notas/vazio.txt: arquivo vazio".to_string()]
    );
    let names: Vec<&str> = src.entries.iter().map(|e| e.name.as_str()).collect();
    assert_eq!(
        names,
        vec![
            "pacote_jul2026.7z/extratos/extrato_jul2026.csv",
            "pacote_jul2026.7z/titulos_api.json",
        ]
    );
    assert_eq!(src.entries[0].tables[0].len(), 18);
    assert_eq!(src.entries[0].tables[0].name, "extratos/extrato_jul2026");
    assert_eq!(src.entries[1].sniff.kind, SourceKind::Json);
    assert_eq!(src.entries[1].tables[0].name, "titulos_api:titulos");
    let ids: std::collections::BTreeSet<&str> =
        src.flatten().iter().map(|s| s.source_id.as_str()).collect();
    assert_eq!(ids.len(), 3);
}

#[test]
fn containers_inside_containers_stay_closed() {
    let ctx = InboxContext::default();
    let sevenz = std::fs::read(golden("escritorio/pacote_jul2026.7z")).unwrap_or_default();
    let msg = std::fs::read(golden("escritorio/boleto_atualizado.msg")).unwrap_or_default();
    let mut buf = std::io::Cursor::new(Vec::new());
    {
        use std::io::Write;
        let mut w = zip::ZipWriter::new(&mut buf);
        let opts = zip::write::SimpleFileOptions::default();
        for (name, bytes) in [("lote.7z.bin", &sevenz), ("mensagem.msg", &msg)] {
            w.start_file(name, opts).unwrap_or_else(|e| panic!("{e}"));
            w.write_all(bytes).unwrap_or_else(|e| panic!("{e}"));
        }
        w.finish().unwrap_or_else(|e| panic!("{e}"));
    }
    let src = parse_bytes("pacote.zip", buf.get_ref(), &ctx).unwrap_or_else(|e| panic!("{e}"));
    let inner_7z = &src.entries[0];
    assert_eq!(inner_7z.sniff.kind, SourceKind::SevenZ);
    assert!(inner_7z.entries.is_empty());
    assert_eq!(
        inner_7z.warnings,
        vec!["pacote.zip/lote.7z.bin: 7z dentro de outro arquivo compactado não é aberto (profundidade máxima 1)".to_string()]
    );
    let inner_msg = &src.entries[1];
    assert_eq!(inner_msg.sniff.kind, SourceKind::Msg);
    assert!(inner_msg.entries.is_empty());
    assert_eq!(events(inner_msg).len(), 1, "the message itself is read");
    assert_eq!(
        inner_msg.warnings,
        vec!["pacote.zip/mensagem.msg: os anexos de uma mensagem dentro de outro arquivo não são abertos (profundidade máxima 1)".to_string()]
    );
}

#[test]
fn twin_variants_inputs_parse() {
    let odt = parse("vantara-twin-escritorio/01_contas_a_receber_protheus_jul2026.odt");
    assert!(odt.warnings.is_empty(), "{:?}", odt.warnings);
    assert_eq!(odt.tables[0].len(), 12);
    let json = parse("vantara-twin-escritorio/02_titulos_unidade_norte_omie_jul2026.json");
    assert_eq!(json.tables[0].len(), 5);
    assert_eq!(role(&json.tables[0], "customer_tax_id"), ColumnRole::TaxId);
    let html = parse("vantara-twin-escritorio/03_extrato_bancario_jul2026.html");
    assert_eq!(html.tables[0].len(), 18);
    let docx = parse("vantara-twin-escritorio/04_caixa_de_entrada_contas_a_pagar.docx");
    let txt = parse("vantara-twin/04_caixa_de_entrada_contas_a_pagar.txt");
    // The inbox pasted into Word reads exactly like the text dump.
    let fields = |s: &ParsedSource| -> Vec<Vec<(String, String)>> {
        s.items
            .iter()
            .map(|i| {
                i.fields
                    .iter()
                    .filter(|(k, _)| *k != "event_id")
                    .map(|(k, v)| (k.clone(), v.render()))
                    .collect()
            })
            .collect()
    };
    assert_eq!(fields(&docx), fields(&txt));
    let carteira = parse("vantara-twin-msg-7z/01_carteira_jul2026.7z");
    assert!(carteira.warnings.is_empty(), "{:?}", carteira.warnings);
    let sizes: Vec<usize> = carteira.entries.iter().map(|e| e.tables[0].len()).collect();
    assert_eq!(sizes, vec![12, 5]);
    let mail = parse("vantara-twin-msg-7z/03_extrato_bancario_jul2026.msg");
    assert_eq!(mail.entries.len(), 1);
    assert_eq!(mail.entries[0].tables[0].len(), 18);
}
